@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button disabled="@(Page <= 1)" @onclick="() => GoToPage(Page - 1)">Previous</button>

        @for (int i = 1; i <= TotalPages; i++)
        {
            var pageNum = i;
            <button class="@(pageNum == Page ? "page-active" : "")"
                    @onclick="() => GoToPage(pageNum)">
                @pageNum
            </button>
        }

        <button disabled="@(Page >= TotalPages)" @onclick="() => GoToPage(Page + 1)">Next</button>
    </nav>
}

@code {
    [Parameter] public int Page { get; set; }
    [Parameter] public int TotalPages { get; set; }
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

