.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.5rem 0;
    border-bottom: 1px solid #eee;
}

.toolbar-sort {
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.toolbar-sort select {
    padding: 0.3rem;
}

.toolbar-info {
    color: #666;
    font-size: 0.9rem;
}

/* Product grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

