.product-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.15s ease;
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

.product-image {
    height: 160px;
    background: #f0f0f0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
}

.product-info {
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
    flex: 1;
}

.product-name {
    font-size: 1rem;
    margin: 0;
}

.product-price {
    font-weight: 600;
    color: #2a2a2a;
    margin: 0;
}

.product-rating {
    color: #f5a623;
    margin: 0;
}

.badge-out-of-stock {
    display: inline-block;
    background: #dc3545;
